<?php

namespace Vnecoms\VendorsCms\Model\Rule\Condition;

class Combine extends \Magento\CatalogWidget\Model\Rule\Condition\Combine
{
    protected $vendorProductFactory;

    public function __construct(
        \Magento\Rule\Model\Condition\Context $context,
        \Magento\CatalogWidget\Model\Rule\Condition\ProductFactory $conditionFactory,
        \Vnecoms\VendorsCms\Model\Rule\Condition\ProductFactory $vendorConditionFactory,
        array $data = []
    ) {
        parent::__construct($context, $conditionFactory, $data);
        $this->vendorProductFactory = $vendorConditionFactory;
        $this->setType('Vnecoms\VendorsCms\Model\Rule\Condition\Combine');
    }

    /**
     * @return array
     */
    public function getNewChildSelectOptions()
    {
        $productAttributes = $this->vendorProductFactory->create()->loadAttributeOptions()->getAttributeOption();
        $attributes = [];
        foreach ($productAttributes as $code => $label) {
            $attributes[] = [
                'value' => 'Vnecoms\VendorsCms\Model\Rule\Condition\Product|'.$code,
                'label' => $label,
            ];
        }
        $conditions = [['value' => '', 'label' => __('Please choose a condition to add.')]];
        $conditions = array_merge_recursive(
            $conditions,
            [
                [
                    'value' => 'Vnecoms\VendorsCms\Model\Rule\Condition\Combine',
                    'label' => __('Conditions Combination'),
                ],
                ['label' => __('Product Attribute'), 'value' => $attributes],
            ]
        );

        return $conditions;
    }

    /**
     * @return object
     */
    public function getAggregatorElement()
    {
        if ($this->getAggregator() === null) {
            foreach (array_keys($this->getAggregatorOption()) as $key) {
                $this->setAggregator($key);
                break;
            }
        }

        return $this->getForm()->addField(
            $this->getPrefix().'__'.$this->getId().'__aggregator',
            'select',
            [
                'name' => $this->elementName.'['.$this->getPrefix().']['.$this->getId().'][aggregator]',
                'values' => $this->getAggregatorSelectOptions(),
                'value' => $this->getAggregator(),
                'value_name' => $this->getAggregatorName(),
                'data-form-part' => $this->getFormName(),
            ]
        )->setRenderer(
            $this->_layout->getBlockSingleton('Vnecoms\VendorsCms\Block\Rule\Editable')
        );
    }

    /**
     * @return string
     */
    public function getAddLinkHtml()
    {
        $src = $this->_assetRepo->getUrl('Vnecoms_VendorsCms::images/rule_component_add.gif');
        $html = '<img src="'.$src.'" class="rule-param-add v-middle" alt="" title="'.__('Add').'"/>';

        return $html;
    }

    /**
     * @return string
     */
    public function getRemoveLinkHtml()
    {
        $src = $this->_assetRepo->getUrl('Vnecoms_VendorsCms::images/rule_component_remove.gif');
        $html = ' <span class="rule-param"><a href="javascript:void(0)" class="rule-param-remove" title="'.__(
            'Remove'
        ).'"><img src="'.$src.'"  alt="" class="v-middle" /></a></span>';

        return $html;
    }

    /**
     * @return \Magento\Framework\Data\Form\Element\Select
     */
    public function getOperatorElement()
    {
        $element = parent::getOperatorElement(); // TODO: Change the autogenerated stub
        $element->setRenderer($this->_layout->getBlockSingleton('Vnecoms\VendorsCms\Block\Rule\Editable'));

        return $element;
    }

    /**
     * @return $this
     */
    public function getAttributeElement()
    {
        if (null === $this->getAttribute()) {
            foreach (array_keys($this->getAttributeOption()) as $option) {
                $this->setAttribute($option);
                break;
            }
        }

        return $this->getForm()->addField(
            $this->getPrefix().'__'.$this->getId().'__attribute',
            'select',
            [
                'name' => $this->elementName.'['.$this->getPrefix().']['.$this->getId().'][attribute]',
                'values' => $this->getAttributeSelectOptions(),
                'value' => $this->getAttribute(),
                'value_name' => $this->getAttributeName(),
                'data-form-part' => $this->getFormName(),
            ]
        )->setRenderer(
            $this->_layout->getBlockSingleton('Vnecoms\VendorsCms\Block\Rule\Editable')
        );
    }

    /**
     * @return \Magento\Rule\Block\Editable
     */
    public function getValueElementRenderer()
    {
        if (strpos($this->getValueElementType(), '/') !== false) {
            return $this->_layout->getBlockSingleton($this->getValueElementType());
        }

        return $this->_layout->getBlockSingleton('Vnecoms\VendorsCms\Block\Rule\Editable');
    }
}
